  "Get started": "ابدأ",
  "Ask your child for their link code — they'll find it in Settings → Family — then enter it to follow their hours.": "اطلب من طفلك رمز الربط — يجده في الإعدادات ← العائلة — ثم أدخله لترى ساعاته.",
