  "Waiting for your OK": "بانتظار موافقتك",
  "Your child is under 13, so these sign-ups reach the organizer only after you approve them.": "طفلك دون 13 عامًا، لذا لا تصل هذه التسجيلات إلى المنظّم إلا بعد موافقتك.",
  "The organizer's waiver: approving also agrees to it for your child": "إقرار المنظّم: موافقتك تعني قبوله نيابةً عن طفلك أيضًا",
  "Approve": "موافقة",
  "Decline": "رفض",
  "Language": "اللغة",
  "Other language…": "لغة أخرى…",
  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "استخدم الزر أدناه لفتح VolunTrack في متصفح هاتفك (Chrome أو Safari) وتسجيل الدخول.",
  "Then use the browser’s translate, as shown below.": "ثم استخدم ترجمة المتصفح كما هو موضّح أدناه.",
  "Use VolunTrack in another language": "استخدم VolunTrack بلغة أخرى",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "يتوفر VolunTrack بالإنجليزية والإسبانية والفيتنامية والصينية، وشاشاته الرئيسية متوفرة أيضًا بالهندية والعربية والبرتغالية والفرنسية والبنغالية والروسية واليابانية. ولأي لغة أخرى، يمكن لمتصفحك ترجمة الصفحة. الخدمة مجانية وتعمل بأكثر من 100 لغة، مثل التاغالوغية والكورية والكريولية الهايتية والألمانية والأردية.",
  "computer": "الحاسوب",
  "Right-click anywhere on the page, choose Translate to…, then pick your language.": "انقر بزر الفأرة الأيمن في أي مكان من الصفحة، واختر ترجمة…، ثم اختر لغتك.",
  "Android phone": "هاتف Android",
  "Tap ⋮ (top right), then Translate…, then pick your language.": "اضغط ⋮ (أعلى اليمين)، ثم ترجمة…، ثم اختر لغتك.",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "اضغط قائمة الصفحة (aA أو الأيقونة على يسار شريط العنوان)، ثم ترجمة….",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "انقر أيقونة الترجمة في شريط العنوان، أو اختر عرض ← ترجمة.",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "ترجمة المتصفح يقوم بها متصفحك وليس VolunTrack، لذا قد لا تكون دقيقة تمامًا. تبقى رسائل البريد بالإنجليزية أو بلغة VolunTrack التي اخترتها.",
  "Open in browser": "افتح في المتصفح",
  "Got it": "فهمت",
