  "Accessibility": "إمكانية الوصول",
  "Make VolunTrack easier to read. These settings are saved on this device only.": "اجعل VolunTrack أسهل في القراءة. تُحفظ هذه الإعدادات على هذا الجهاز فقط.",
  "Brighter text, stronger borders and focus outlines, and underlined links.": "نص أوضح، وحدود وحلقات تركيز أسمك، وروابط مسطّرة.",
  "A font that keeps similar letters like I, l and 1 easy to tell apart. Can help with dyslexia or low vision.": "خط يسهّل التمييز بين الحروف المتشابهة مثل I وl و1. قد يساعد في عسر القراءة أو ضعف البصر.",
  "The short version": "الملخص",
  "The full": "النص الكامل",
  "are what count.": " هو المرجع النهائي.",
  "Set a goal and your dashboard will show how close you are. You can change it any time in Settings.": "حدّد هدفًا وستعرض لوحة التحكم مدى قربك منه. يمكنك تغييره في أي وقت من الإعدادات.",
  "Goal name": "اسم الهدف",
  "e.g. Summer service hours": "مثل ساعات الخدمة الصيفية",
  "Due by (optional)": "الموعد النهائي (اختياري)",
  "Skip for now": "تخطَّ الآن",
