  "Link your school": "اربط مدرستك",
  "You're linked to your school. Hours you log will show up for your coordinator to review.": "أنت مرتبط بمدرستك. ستظهر الساعات التي تسجّلها لمنسّقك ليراجعها.",
  "School code": "رمز المدرسة",
  "Go to my dashboard": "اذهب إلى لوحة التحكم",
  "Password recovery code:": "رمز استعادة كلمة المرور:",
  "Password recovery code ready": "رمز استعادة كلمة المرور جاهز",
  "A password recovery code has been emailed to": "أرسلنا رمز استعادة كلمة المرور إلى",
  ". It expires in 15 minutes.": ". تنتهي صلاحيته بعد 15 دقيقة.",
  "Look for an email from": "ابحث عن رسالة من",
  "Don't see it? Check the Spam folder and Promotions/Updates tab.": "لا تراها؟ تحقّق من الرسائل غير المرغوب فيها وتبويبَي العروض/التحديثات.",
  "This deployment is a static site, so there’s no email server reachable from here. The password recovery code is shown below — only you can see this screen.": "هذا موقع ثابت، لذا لا يمكن الوصول إلى خادم بريد من هنا. رمز استعادة كلمة المرور معروض أدناه — لا يرى هذه الشاشة أحد غيرك.",
  "Email delivery is not available right now": "تعذّر إرسال البريد الآن",
  ". Use the code below to continue.": ". استخدم الرمز أدناه للمتابعة.",
  "Add": "أضف",
  "to your": "إلى",
  "and restart the backend to enable real email.": "، وأعد تشغيل الخادم لتفعيل البريد الحقيقي.",
  "Retrying…": "جارٍ إعادة المحاولة…",
  "Continue to reset": "تابع إلى إعادة التعيين",
  "Forgot password?": "نسيت كلمة المرور؟",
  "Enter the email on your account and we’ll email a password recovery code.": "أدخل بريد حسابك وسنرسل إليك رمز استعادة كلمة المرور.",
  "SMTP isn’t configured. Add": "SMTP غير مُعدّ. أضف",
