  "Doesn't count for now. Edit the entry to fix it, and it goes back to your school.": "لا يُحتسب حاليًا. عدّل الإدخال لإصلاحه، وسيعود إلى مدرستك.",
  "References": "التوصيات",
  "Ask a supervisor or organizer who saw you volunteer to write a few lines about it, for college and scholarship applications. They get an email link and don’t need an account.": "اطلب من مشرف أو منظّم رآك تتطوع أن يكتب بضعة أسطر عن ذلك، لطلبات الالتحاق بالجامعة والمنح الدراسية. يصله رابط عبر البريد ولا يحتاج إلى حساب.",
