  "Mobile sync PIN": "رمز مزامنة الهاتف",
  "Generate a 5-digit PIN to sync your account with your laptop. Enter it on your computer within 15 minutes — it works once.": "أنشئ رمزًا من 5 أرقام لمزامنة حسابك مع حاسوبك المحمول. أدخله على حاسوبك خلال 15 دقيقة — يعمل مرة واحدة.",
  "Generate a 5-digit PIN to sync your account with the mobile app. Enter it on your phone within 15 minutes — it works once.": "أنشئ رمزًا من 5 أرقام لمزامنة حسابك مع تطبيق الهاتف. أدخله على هاتفك خلال 15 دقيقة — يعمل مرة واحدة.",
