  "Set up weekly or one-time reminders so you never forget to log your volunteer hours.": "أعدّ تذكيرات أسبوعية أو لمرة واحدة حتى لا تنسى أبدًا تسجيل ساعات تطوعك.",
  "Manage reminders": "أدِر التذكيرات",
  "Privacy": "الخصوصية",
  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "ساعاتك المسجّلة محفوظة على هذا الجهاز. إذا أنشأت حسابًا، فإن بعض الميزات أعلاه (المشاركة العائلية، وربط المدرسة، والمزامنة بين الأجهزة، والتحقق بخطوتين) تحفظ بيانات على خادمنا أيضًا. سجّل الخروج أدناه لمسح جلستك.",
  "Signed in as": "مسجّل الدخول باسم",
  "Role:": "الدور:",
  "Admin inbox": "صندوق وارد المسؤول",
  "Review contact form submissions.": "راجع رسائل نموذج التواصل.",
