  "Contact us": "تواصل معنا",
  "Sign out": "تسجيل الخروج",
  "Warning": "تحذير",
  "Deleting your account erases it from this device and from our servers, and cannot be undone.": "حذف حسابك يمحوه من هذا الجهاز ومن خوادمنا، ولا يمكن التراجع عنه.",
  "Delete account": "حذف الحساب",
  "Remove your account and your VolunTrack data — from this device and, if you have an account with us, from our servers too. This action cannot be undone.": "أزل حسابك وبيانات VolunTrack الخاصة بك — من هذا الجهاز، ومن خوادمنا أيضًا إذا كان لديك حساب معنا. لا يمكن التراجع عن هذا الإجراء.",
  "Confirm account deletion": "تأكيد حذف الحساب",
  "This is permanent. Your volunteer logs, goals, achievements, and reminder data will be erased.": "هذا نهائي. ستُمحى سجلات تطوعك وأهدافك وإنجازاتك وبيانات التذكيرات.",
  "Type {word} to confirm.": "اكتب {word} للتأكيد.",
  "Type delete to confirm": "اكتب delete للتأكيد",
  "Then type your email address, {email}.": "ثم اكتب بريدك الإلكتروني، {email}.",
  "Then re-enter your password.": "ثم أعد إدخال كلمة المرور.",
  "your email address": "بريدك الإلكتروني",
  "Deleting…": "جارٍ الحذف…",
  "Yes, delete everything": "نعم، احذف كل شيء",
  "Passkey added. You can use it the next time you sign in.": "تمت إضافة مفتاح المرور. يمكنك استخدامه في المرة القادمة التي تسجّل فيها الدخول.",
  "Passkey removed.": "تمت إزالة مفتاح المرور.",
  "Passkeys": "مفاتيح المرور",
  "After your password, confirm it’s you with Face ID, Touch ID, your fingerprint or your device PIN instead of typing a code. Keep your authenticator app too — its backup codes are how you get back in if you lose every device with a passkey.": "بعد كلمة المرور، أكّد هويتك باستخدام Face ID أو Touch ID أو بصمة الإصبع أو رمز الجهاز بدلًا من كتابة رمز. احتفظ بتطبيق المصادقة أيضًا — رموز النسخ الاحتياطي الخاصة به هي طريقتك للعودة إذا فقدت كل جهاز عليه مفتاح مرور.",
  "Added {date}": "أُضيف في {date}",
  "last used {date}": "آخر استخدام {date}",
  "This device can’t create passkeys.": "لا يمكن لهذا الجهاز إنشاء مفاتيح مرور.",
  "Add a passkey": "أضف مفتاح مرور",
  "If you lose this device, sign in with one of these instead of your passkey. Each works once, and this is the only time they're shown.": "إذا فقدت هذا الجهاز، سجّل الدخول بأحد هذه الرموز بدلًا من مفتاح المرور. يعمل كل منها مرة واحدة، وهذه هي المرة الوحيدة التي تُعرض فيها.",
  "I've saved them": "لقد حفظتها",
  "Free club plan": "خطة النادي المجانية",
