  "Confirmation submitted": "تم إرسال التأكيد",
  "Confirmation rejected": "تم رفض التأكيد",
  "We received your bank confirmation number. Please allow 3–5 business days for our team to verify it — you'll get an approval email once it's confirmed, and student uploads and management will unlock automatically.": "تلقّينا رقم تأكيد التحويل البنكي. يرجى الانتظار 3–5 أيام عمل ليتحقق منه فريقنا — ستتلقى رسالة موافقة بمجرد تأكيده، وستُفتح رفوعات الطلاب وإدارتهم تلقائيًا.",
  "Your confirmation could not be verified.": "تعذّر التحقق من تأكيدك.",
  "Please double-check the number and resubmit.": "يرجى مراجعة الرقم وإعادة إرساله.",
  "Please complete payment using the details below, then enter the bank confirmation number.": "يرجى إتمام الدفع باستخدام التفاصيل أدناه، ثم إدخال رقم التأكيد البنكي.",
  "Please enter your bank confirmation / reference number": "يرجى إدخال رقم التأكيد / المرجع البنكي",
  "e.g. WIRE-12345 or check #4821": "مثلًا: WIRE-12345 أو شيك رقم 4821",
  "Submitting…": "جارٍ الإرسال…",
  "Submit confirmation": "أرسل التأكيد",
  "Only the school's primary admin account can submit a payment confirmation.": "لا يمكن إرسال تأكيد الدفع إلا من حساب المسؤول الرئيسي للمدرسة.",
