  "No hour requirement applies to {grade}. Add one for this grade (or a school-wide total) in Requirements.": "لا يوجد عدد ساعات مطلوب ينطبق على {grade}. أضف واحدًا لهذا الصف (أو إجماليًا للمدرسة كلها) في المتطلبات.",
  "Who in a grade met the hour requirement, due {date}.": "من في الصف استوفى الساعات المطلوبة، الموعد {date}.",
