  "1 student has no grade on their account and is not in any grade’s report.": "طالب واحد ليس في حسابه صف، وليس مدرجًا في تقرير أي صف.",
  "{n} students have no grade on their account and are not in any grade’s report.": "{n} طالب ليس في حساباتهم صف، وليسوا مدرجين في تقرير أي صف.",
