  "Branding saved. Sign-in pages on your domain pick it up within 10 minutes.": "تم حفظ الهوية البصرية. ستظهر في صفحات تسجيل الدخول على نطاقك خلال 10 دقائق.",
  "Loading branding…": "جارٍ تحميل الهوية البصرية…",
  "Accent colour": "اللون المميز",
  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "قيمة سداسية عشرية (hex). تُستخدم للمسات اللونية في صفحة تسجيل الدخول — وليس للنص أو خلفيات الأزرار، لذا يبقى أي لون مقروءًا. اتركه فارغًا لاستخدام أخضر VolunTrack.",
  "Enter a hex value like #2f855a.": "أدخل قيمة hex مثل #2f855a.",
  "Preview": "معاينة",
  "Save branding": "احفظ الهوية البصرية",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "تنطبق هذه الهوية البصرية على أسماء النطاقات الخاصة بمنظمتك. كل مدرسة تحدد هويتها البصرية بشكل منفصل.",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "تتغير صفحة تسجيل الدخول الخاصة بمدرستك فقط. يبقى اسم VolunTrack وشعاره على الموقع الأساسي.",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "لا تظهر الهوية البصرية إلا على اسم نطاقك الخاص. ليس لديك نطاق مفعّل بعد — أعدّ واحدًا من النطاق المخصص أولًا، ثم سيظهر كل ما تحفظه هنا في صفحة تسجيل الدخول الخاصة به.",
  "Shown at sign-in on": "تظهر عند تسجيل الدخول على",
  "Set how many hours your students need (one total, or per grade) to see who is behind.": "حدّد عدد الساعات التي يحتاجها طلابك (إجمالي واحد، أو لكل صف) لترى من المتأخر.",
  "Allow pop-ups for this site to print the certificates.": "اسمح بالنوافذ المنبثقة لهذا الموقع لطباعة الشهادات.",
  "Print certificates ({n})": "اطبع الشهادات ({n})",
