  "Yes, send": "نعم، أرسل",
  "Email reminder": "تذكير عبر البريد",
  "Each student gets at most one reminder every {n} days.": "يتلقى كل طالب تذكيرًا واحدًا على الأكثر كل {n} يوم.",
  "{n} of {total} students still have hours to go": "لا يزال {n} من {total} طالب لديهم ساعات متبقية",
