  "reminded {date}": "ذُكّر في {date}",
  "Email 1 student how many hours they have left?": "إرسال بريد إلى طالب واحد بعدد الساعات المتبقية له؟",
  "Email {n} students how many hours they have left?": "إرسال بريد إلى {n} طالب بعدد الساعات المتبقية لهم؟",
  "Say why, so the student can fix it.": "اذكر السبب، ليتمكن الطالب من إصلاحه.",
  "Entries no supervisor or event organizer has confirmed. They count for now; approve them, or send one back with a reason and it stops counting until the student fixes it.": "إدخالات لم يؤكدها أي مشرف أو منظّم فعالية. تُحتسب حاليًا؛ وافق عليها، أو أعد أحدها مع ذكر السبب فيتوقف احتسابه حتى يصلحه الطالب.",
  "All ({n})": "الكل ({n})",
