  "not on your approved list": "ليس في قائمتك المعتمدة",
  "proof attached": "الإثبات مرفق",
  "What should the student fix? They see this.": "ما الذي يجب أن يصلحه الطالب؟ سيرى هذا.",
  "Send back": "إعادة",
  "Showing the first 200. Approve or send back some to see more.": "يُعرض أول 200. وافق على بعضها أو أعدها لترى المزيد.",
  "Build report": "أنشئ التقرير",
