  "Detail CSV": "CSV تفصيلي",
  "Summary CSV": "CSV ملخص",
  "Summary PDF": "PDF ملخص",
  "This range hit the {n}-row limit, so the export is incomplete. Narrow the dates and run it again.": "بلغ هذا النطاق حد {n} صف، لذا التصدير غير مكتمل. ضيّق التواريخ وأعد التشغيل.",
  "Showing 25 of {n}. The exports contain every student.": "يُعرض 25 من {n}. تحتوي ملفات التصدير على كل الطلاب.",
  "Loading domains…": "جارٍ تحميل النطاقات…",
  "Custom domains can be claimed and their ownership verified, but this server cannot issue certificates yet, so a domain cannot go live. Contact VolunTrack support.": "يمكن المطالبة بالنطاقات المخصصة والتحقق من ملكيتها، لكن هذا الخادم لا يستطيع إصدار الشهادات بعد، لذا لا يمكن تفعيل النطاق. تواصل مع دعم VolunTrack.",
  "Ownership verified": "تم التحقق من الملكية",
  "Ownership not verified yet": "لم يتم التحقق من الملكية بعد",
  "Add these two records at your DNS provider. The TXT record proves you own the domain; the CNAME sends visitors to VolunTrack.": "أضف هذين السجلين لدى مزوّد DNS الخاص بك. سجل TXT يثبت ملكيتك للنطاق؛ وسجل CNAME يوجّه الزوار إلى VolunTrack.",
