  "Your tasks": "مهامك",
  "Guests of approved volunteers": "ضيوف المتطوعين الموافق عليهم",
  "Show-up rate counts volunteers you approved who were marked present or checked in, out of those plus anyone marked absent. Excused volunteers and anyone not yet marked aren't counted. Hours are approved hours logged on the task.": "نسبة الحضور تحتسب المتطوعين الذين وافقت عليهم وسُجّلوا حاضرين أو سجّلوا حضورهم، من بين هؤلاء إضافة إلى من سُجّلوا غائبين. لا يُحتسب المعذورون ومن لم يُسجَّلوا بعد. الساعات هي الساعات الموافق عليها المسجّلة على المهمة.",
  "QR code to sign on a phone": "رمز QR للتوقيع على الهاتف",
  "Fall": "الخريف",
  "Spring": "الربيع",
  "Term goals": "أهداف الفصول الدراسية",
  "Split the year into terms, each with its own hours. Students see this term’s progress, and you see who is behind this term. Hours count toward the term they were logged in.": "قسّم العام إلى فصول، لكل منها ساعاتها. يرى الطلاب تقدّم الفصل الحالي، وترى أنت من المتأخر في هذا الفصل. تُحتسب الساعات للفصل الذي سُجّلت فيه.",
  "Term name": "اسم الفصل",
  "+ Add a term": "+ أضف فصلًا",
  "Feature your review?": "نعرض مراجعتك؟",
  "You submitted a review. Do you want it considered for the public testimonials on our site?": "أرسلت مراجعة. هل تريد أن ننظر في عرضها ضمن الشهادات العامة على موقعنا؟",
  "No thanks": "لا، شكرًا",
  "Yes, feature it": "نعم، اعرضها",
