  "Resend code": "أعد إرسال الرمز",
  "Love VolunTrack?": "تحب VolunTrack؟",
  "You've logged your first volunteer session. We'd love to hear how it's going for you!": "سجّلت أول جلسة تطوع لك. يسعدنا أن نسمع كيف تسير الأمور معك!",
  "Rate your experience": "قيّم تجربتك",
  "Tell us what you like or what could be better...": "أخبرنا بما يعجبك أو ما يمكن تحسينه...",
