  "Add co-adviser": "أضف مرشدًا مشاركًا",
  "Share the join link or put the flyer up. Students who use it land on your roster.": "شارك رابط الانضمام أو علّق المنشور. الطلاب الذين يستخدمونه يظهرون في قائمتك.",
  "Approve hours as they come in, here on the Students tab.": "وافق على الساعات فور وصولها، هنا في تبويب الطلاب.",
