  "Minimum stay for hours to count": "الحد الأدنى للبقاء لاحتساب الساعات",
  "{n} minutes": "{n} دقيقة",
  "Someone who checks out sooner still gets an entry, but you approve or reject it on My Tasks.": "من يسجّل انصرافه قبل ذلك يحصل على إدخال، لكنك توافق عليه أو ترفضه في مهامي.",
  "Couldn’t load the CAPTCHA. Refresh the page and try again.": "تعذّر تحميل اختبار CAPTCHA. حدّث الصفحة وحاول مرة أخرى.",
