  "School or organization partnership": "شراكة مع مدرسة أو منظمة",
  "That doesn't look like a VolunTrack account ID (e.g. VT-SCH-4F2K9A).": "لا يبدو هذا معرّف حساب VolunTrack (مثل VT-SCH-4F2K9A).",
  "No account has that ID. Check it against your invoice, or leave it blank.": "لا يوجد حساب بهذا المعرّف. قارنه بفاتورتك، أو اتركه فارغًا.",
