  "Get started free": "ابدأ مجانًا",
  "Track your hours with VolunTrack": "تابع ساعاتك مع VolunTrack",
  "Free for students. Log hours in a minute, see your goal, and export a report when it’s due.": "مجاني للطلاب. سجّل الساعات في دقيقة، وشاهد هدفك، وصدّر تقريرًا عند حلول موعده.",
