  "Read the guide": "اقرأ الدليل",
  "Guides": "الأدلة",
  "More guides": "المزيد من الأدلة",
  "Or scan with your phone": "أو امسح بهاتفك",
  "Sign in on your phone and scan. A code appears under your name here: type it on your phone.": "سجّل الدخول على هاتفك وامسح. يظهر رمز تحت اسمك هنا: اكتبه على هاتفك.",
  "Could not open the kiosk.": "تعذّر فتح جهاز الاستقبال.",
  "Couldn’t reach VolunTrack. Check the internet connection.": "تعذّر الوصول إلى VolunTrack. تحقّق من اتصال الإنترنت.",
  "Set a kiosk exit code": "عيّن رمز الخروج من جهاز الاستقبال",
  "Pick 4 digits only you know. You’ll need them to leave the kiosk or unlock a name, so volunteers can’t get into your account.": "اختر 4 أرقام لا يعرفها غيرك. ستحتاجها لمغادرة جهاز الاستقبال أو فتح قفل اسم، حتى لا يتمكن المتطوعون من الدخول إلى حسابك.",
  "Check in and out": "سجّل الحضور والانصراف",
  "Organizer: exit kiosk": "المنظّم: الخروج من جهاز الاستقبال",
  "Tap your name, then enter the 6-digit PIN from your approval email.": "اضغط اسمك، ثم أدخل الرمز المكوّن من 6 أرقام من رسالة الموافقة.",
  "Code for {name}": "الرمز لـ {name}",
  "No PIN": "لا يوجد رمز",
