  "Exit kiosk": "الخروج من جهاز الاستقبال",
  "Unlock {name}": "افتح قفل {name}",
  "Organizer: enter your 4-digit kiosk code.": "المنظّم: أدخل رمز جهاز الاستقبال المكوّن من 4 أرقام.",
  "Signed": "موقّع",
  "Waiting for your signature": "بانتظار توقيعك",
