  "Several time slots or roles, each with its own spots. Volunteers pick one.": "عدة فترات زمنية أو أدوار، لكل منها أماكنها. يختار المتطوعون واحدة.",
  "Pick a pin on the map above so this task can be sorted by distance.": "اختر دبوسًا على الخريطة أعلاه ليمكن ترتيب هذه المهمة حسب المسافة.",
