  "Event": "الفعالية",
  "You haven't posted any tasks yet.": "لم تنشر أي مهام بعد.",
  "Average rating from volunteers who came": "متوسط التقييم من المتطوعين الذين حضروا",
  "Comments are anonymous. If one breaks the rules, contact us from Help.": "التعليقات مجهولة الهوية. إذا خالف أحدها القواعد، تواصل معنا من المساعدة.",
  "Check-in QR": "رمز QR للحضور",
  "A tablet at the door: volunteers tap their name and enter the PIN from their approval email.": "جهاز لوحي عند الباب: يضغط المتطوعون أسماءهم ويُدخلون الرمز من رسالة الموافقة.",
