  "Important info — approved volunteers only": "معلومات مهمة — للمتطوعين الموافق عليهم فقط",
  "Volunteers needed": "عدد المتطوعين المطلوب",
  "Message every approved volunteer": "راسل كل متطوع موافق عليه",
  "Bring gloves and water. Park at the back of the lot.": "أحضر قفازات وماءً. اركن في الجزء الخلفي من الموقف.",
  "Sent one message per person — volunteers never see each other's addresses.": "تُرسل رسالة واحدة لكل شخص — لا يرى المتطوعون عناوين بعضهم أبدًا.",
  "Cancel this event": "ألغِ هذه الفعالية",
  "Reason (optional) — included in the email": "السبب (اختياري) — يُضمَّن في الرسالة",
  "Everyone signed up is emailed. Attendance already recorded is kept, and the event cannot be reopened.": "يُرسل بريد إلى كل المسجّلين. يُحتفظ بالحضور المسجّل بالفعل، ولا يمكن إعادة فتح الفعالية.",
  "Keep it": "أبقِها",
