  "Volunteers signed up": "المتطوعون المسجّلون",
  "Fill in shift lengths": "املأ مدد المناوبات",
  "My Students": "طلابي",
  "No approved students yet — approve a signup above to see them here.": "لا يوجد طلاب موافق عليهم بعد — وافق على تسجيل أعلاه لتراهم هنا.",
  "No logged hours yet.": "لا توجد ساعات مسجّلة بعد.",
  "Signed & approved": "موقّع وموافق عليه",
