  "Paste your organization's waiver or release. Volunteers agree by typing their name; for anyone under 18, a parent or guardian agrees too.": "الصق إقرار المسؤولية أو إخلاء المسؤولية الخاص بمنظمتك. يوافق المتطوعون بكتابة أسمائهم؛ ولمن هم دون 18 عامًا، يوافق أحد الوالدين أو الوصي أيضًا.",
  "Thank you": "شكرًا لك",
  "Almost done. Pick your account type and fill in the rest. You won’t need a password: sign in with the same button next time.": "أوشكت على الانتهاء. اختر نوع حسابك واملأ الباقي. لن تحتاج إلى كلمة مرور: سجّل الدخول بالزر نفسه في المرة القادمة.",
  "Log some hours first, then make your résumé.": "سجّل بعض الساعات أولًا، ثم أنشئ سيرتك الذاتية.",
