  "Sign-in didn't complete": "لم يكتمل تسجيل الدخول",
  "Signing you in…": "جارٍ تسجيل دخولك…",
  "Finishing up with your school's login.": "جارٍ الإنهاء مع تسجيل الدخول الخاص بمدرستك.",
