  "Issued by VolunTrack for": "أصدره VolunTrack لـ",
  "Signed with a signing key that has since been rotated. It is still valid.": "موقّع بمفتاح توقيع تم تغييره منذ ذلك الحين. لا يزال صالحًا.",
  "Approved hours": "الساعات الموافق عليها",
  "Verification": "التحقق",
  "Found a bug, have a feature request, or just want to say hi? We'd love to hear from you.": "وجدت مشكلة تقنية، أو لديك طلب ميزة، أو تريد فقط إلقاء التحية؟ يسعدنا أن نسمع منك.",
  "Check that a VolunTrack transcript is genuine and has not been changed since it was issued. No account needed. The file is checked by our server and not stored.": "تحقّق من أن سجل VolunTrack أصلي ولم يتغير منذ إصداره. لا حاجة إلى حساب. يفحص خادمنا الملف ولا يحفظه.",
  "Finish setting up your organization": "أكمل إعداد منظمتك",
  "Register your organization": "سجّل منظمتك",
