  "Walk-in": "حضور دون تسجيل",
  "Allow walk-ins": "اسمح بالحضور دون تسجيل",
  "People who didn’t sign up can scan this code to join and check in, while there are spots left.": "يمكن للأشخاص الذين لم يسجّلوا مسح هذا الرمز للانضمام وتسجيل الحضور، ما دامت هناك أماكن متاحة.",
  "Join as a walk-in?": "تنضم دون تسجيل مسبق؟",
